head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isUpdate = false;
scwin.storageId = "";

// 수정 여부

///////// 2. 초기화 영역 /////////
            /**
             * @method
             * @name onpageload
             * @description 화면 진입점 — storageId 를 수신하고 서식분류 정보를 동적 서브미션으로 조회해 콜백(sbm_upclss_submitdone)을 직접 호출한 뒤, 시장구분 공통코드(LD_MKT_TP_CD)를 조회한다.
             * @returns {void}
             * @hidden N
             * @example (body ev:onpageload 바인딩으로 자동 호출)
             */
            scwin.onpageload = async function() {

                scwin.storageId = $c.data.getParameter("storageId");

                // 상장고시 시장구분코드
                const list = ["LD_MKT_TP_CD"];
                const params = {"cdEngNmList":list};

                // 서식분류 정보 조회
                const sbmOptions = {
                    id : "sbm_upclss",
                    action : "/api/code/form-upclss",
                    method : "get",
                    processMsg : "공통코드 조회중..."
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                scwin.sbm_upclss_submitdone(sbmRtn);

                // 시장구분 정보 조회
                $c.sbm.execute(sbm_ldMktTpCd, params);	
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name ibx_tpClssCd_onkeyup
             * @description 유형분류코드 키 입력 — 한글 입력을 차단하고 숫자만 허용한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_tpClssCd_onkeyup(e);
             */
            scwin.ibx_tpClssCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_tpClssCd);
                // 양수만 되게 수정
                ibx_tpClssCd.setValue((ibx_tpClssCd.getValue()).replace(/[^0-9]/g, ""));
            };

            /**
             * @method
             * @name ibx_disclsTpClssEngNm_onkeyup
             * @description 공시유형분류 영문명 키 입력 — 한글 입력을 차단한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_disclsTpClssEngNm_onkeyup(e);
             */
            scwin.ibx_disclsTpClssEngNm_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_disclsTpClssEngNm);
            };

            /**
             * @method
             * @name btn_save_onclick
             * @description [저장] 버튼 클릭 — 입력값 검증 후(변경 모드면 update 액션으로 전환) 버튼 이중 클릭을 방지하고 저장(sbm_save)을 실행한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_save_onclick(e);
             */
            scwin.btn_save_onclick = async function (e) {

                // validation 체크
                if (!$c.tms.validateGroupTms("grp_input")) return;

                if (scwin.isUpdate) {                                           
                    $c.sbm.setAction(sbm_save, "/api/code/type-clss/update/" + dma_save.get("formUpclssCd") + "/" + dma_save.get("tpClssCd") + "/" + dma_save.get("ldMktTpCd"));
                }
                // 이중 클릭 방지
                btn_save.setDisabled(true);
                // 코드 정보 저장
                $c.sbm.execute(sbm_save, dma_save.getJSON());                
            };

            /**
             * @method
             * @name btn_close_onclick
             * @description [취소/닫기] 버튼 클릭 — 팝업을 닫는다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_close_onclick(e);
             */
            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_upclss_submitdone
             * @description 서식분류 조회 콜백 — 서식대분류 셀렉트박스를 구성한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbm_upclss_submitdone(sbmRtn);
             */
            scwin.sbm_upclss_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_formUpclssCd, "formUpclssNm", "formUpclssCd");
                } else {
                    $c.win.alert(result.message);
                }                
            };

            /**
             * @method
             * @name sbm_ldMktTpCd_submitdone
             * @description 시장구분 공통코드 조회(sbm_ldMktTpCd) 콜백 — 시장구분 셀렉트박스를 구성하고, 변경 모드 파라미터가 있으면 지연 후 값 설정·입력 비활성·버튼명 변경으로 변경 모드로 전환한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_ldMktTpCd ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_ldMktTpCd_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                } else {
                    $c.win.alert(result.message);    
                }               

                setTimeout(function () {                                        
                    const formUpclssCd = $c.data.getParameter("formUpclssCd");                                                                     
                    if (!$c.util.isEmpty(formUpclssCd)) {
                        dma_save.set("formUpclssCd", formUpclssCd);
                        dma_save.set("tpClssCd", $c.data.getParameter("tpClssCd"));
                        dma_save.set("ldMktTpCd", $c.data.getParameter("ldMktTpCd"));
                        dma_save.set("disclsTpClssNm", $c.data.getParameter("disclsTpClssNm"));
                        dma_save.set("disclsTpClssEngNm", $c.data.getParameter("disclsTpClssEngNm"));

                        sbx_formUpclssCd.setDisabled(true);
                        ibx_tpClssCd.setDisabled(true);
                        sbx_ldMktTpCd.setDisabled(true);
                        btn_save.setValue("변경 저장");
                        scwin.isUpdate = true;
                    }
                }, 100);             
            };

            /**
             * @method
             * @name sbm_save_submitdone
             * @description 저장(sbm_save) 콜백 — 성공 시 완료 알림 후 refreshYn("Y")·storageId 를 담아 팝업을 닫고, 실패 시 오류 메시지를 알린다. 버튼 이중 클릭 방지를 해제한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_save ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    const params = {};
                    params.refreshYn = "Y";
                    params.storageId = scwin.storageId;

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
                // 이중 클릭 해제
                btn_save.setDisabled(false);
            };
